216	        Set<Long> clashing = new HashSet<>();
217	        for (Person p : people.findBySheetIdOrderByIdAsc(sheetId)) {
218	            if (names(p).stream().anyMatch(n -> holders.getOrDefault(n, Set.of()).stream()
219	                    .anyMatch(id -> !id.equals(p.getId())))) {
